// GHL puede enviar los datos en el body o dentro de customData.
const webhook = $('Webhook').first().json;
const body = webhook.body || {};
const rawCustomData = body.customData || body.custom_data || {};
let customData = rawCustomData;
if (typeof rawCustomData === 'string') {
  try { customData = JSON.parse(rawCustomData); } catch (error) { customData = {}; }
}
const value = (...keys) => {
  for (const key of keys) {
    const candidate = body[key] ?? customData[key];
    if (candidate !== undefined && candidate !== null && String(candidate).trim()) return String(candidate).trim();
  }
  return '';
};

return [{
  json: {
    locationId: value('locationId', 'location_id'),
    contactId: value('contactId', 'contact_id'),
    contactName: value('contactName', 'contact_name', 'name', 'full_name'),
    contactPhone: value('contactPhone', 'contact_phone', 'phone'),
    contactDocument: value('contactDocument', 'contact_document', 'documento_de_identidad', 'document'),
    contactAddress: value('contactAddress', 'contact_address', 'direccion_de_envio', 'address1'),
  },
}];

// Solo se leen los mensajes nuevos: los posteriores a `since`, que la app calcula así:
// - con un pedido abierto de hoy (sin despachar): el último mensaje que ya se leyó en ese pedido;
// - sin pedido abierto: lo más reciente entre las 00:00 de hoy en Bogotá y el último despacho.
// Así un pedido despachado o de otro día nunca se vuelve a leer ni a sumar.
const input = $('Normalizar entrada').first().json;
const context = $('Contexto del pedido').first().json;
const response = $input.first().json;
const raw = response.body?.messages;
const messages = Array.isArray(raw) ? raw : Array.isArray(raw?.messages) ? raw.messages : [];
const timeZone = 'America/Bogota';
const dayKey = (date) => new Intl.DateTimeFormat('en-CA', {
  timeZone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).formatToParts(date).filter((part) => part.type !== 'literal').map((part) => part.value).join('-');
const parseDate = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const numeric = Number(value);
  const date = Number.isFinite(numeric)
    ? new Date(numeric < 1e12 ? numeric * 1000 : numeric)
    : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
};
const collectImageUrls = (message) => {
  const found = [];
  const visit = (value) => {
    if (!value) return;
    if (typeof value === 'string') {
      if (/^https?:\/\//i.test(value)) found.push(value);
      return;
    }
    if (Array.isArray(value)) return value.forEach(visit);
    if (typeof value === 'object') Object.values(value).forEach(visit);
  };
  visit(message.attachments);
  visit(message.meta?.attachments);
  visit(message.messageAttachments);
  const contentType = String(message.contentType || '').toLowerCase();
  const imageMessage = contentType.startsWith('image/') || /image|photo/i.test(String(message.messageType || ''));
  return [...new Set(found)].filter((url) => imageMessage || /\.(?:jpe?g|png|gif|webp|heic|svg)(?:$|[?#])/i.test(url));
};

// Si la app no respondió, se usa solo el día actual y se ajusta el pedido abierto (comportamiento anterior).
const contextOk = context.statusCode >= 200 && context.statusCode < 300;
const openOrder = contextOk ? context.body?.openOrder || null : null;
const since = contextOk && context.body?.since ? new Date(context.body.since) : null;

const today = dayKey(new Date());
const newMessages = messages
  .map((message) => ({ ...message, parsedDate: parseDate(message.dateAdded || message.createdAt || message.dateUpdated) }))
  .filter((message) => message.parsedDate && dayKey(message.parsedDate) === today)
  .filter((message) => !since || message.parsedDate > since)
  .sort((a, b) => a.parsedDate - b.parsedDate);

const turns = [];
const imageUrls = [];
for (const message of newMessages) {
  const role = message.direction === 'inbound' ? 'CLIENTE' : 'FRUTITODO';
  const text = typeof message.body === 'string' ? message.body.trim() : '';
  const attachments = collectImageUrls(message);
  if (text) turns.push(`${role}: ${text}`);
  for (const url of attachments) {
    turns.push(`${role}: [IMAGEN O ARCHIVO ADJUNTO: ${url}]`);
    if (message.direction === 'inbound') imageUrls.push(url);
  }
}

const inbound = newMessages.filter((message) => message.direction === 'inbound');
const lastInbound = inbound.at(-1);
return [{
  json: {
    transcript: turns.join('\n'),
    turns: turns.length,
    inboundMessages: inbound.length,
    imageUrls: [...new Set(imageUrls)].slice(-10),
    readStatus: response.statusCode,
    bogotaDay: today,
    contextOk,
    openOrder,
    // El siguiente llamado empieza después del último mensaje leído aquí.
    contextUntil: newMessages.at(-1)?.parsedDate?.toISOString() || null,
    idempotencySeed: `${input.contactId}|${today}|${lastInbound?.id || lastInbound?.parsedDate?.toISOString() || "sin-mensaje-entrante"}`,
  },
}];

