Dirección CRM: ${contact.contactAddress || 'vacía'}

${current}

MENSAJES NUEVOS, del más antiguo al más reciente:
${transcript.transcript || '(sin mensajes nuevos)'}`;
  const content = [{ type: 'text', text: context }, ...transcript.imageUrls.map((url) => ({ type: 'image_url', image_url: { url } }))];
  const schema = {"type":"object","additionalProperties":false,"required":["ok","error","action","customer","delivery","paymentMethod","items","rawOrderText","notes"],"properties":{"ok":{"type":"boolean"},"error":{"type":["string","null"]},"action":{"type":"string","enum":["anexo","nuevo"]},"customer":{"type":"object","additionalProperties":false,"required":["name","phone","document"],"properties":{"name":{"type":["string","null"]},"phone":{"type":["string","null"]},"document":{"type":["string","null"]}}},"delivery":{"type":"object","additionalProperties":false,"required":["type","address"],"properties":{"type":{"type":"string","enum":["domicilio","recogida"]},"address":{"type":["string","null"]}}},"paymentMethod":{"type":["string","null"]},"items":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["name","quantity","unit","rawText"],"properties":{"name":{"type":"string"},"quantity":{"type":"number"},"unit":{"type":["string","null"]},"rawText":{"type":"string"}}}},"rawOrderText":{"type":"string"},"notes":{"type":["string","null"]}}};
  return JSON.stringify({ model: $('Config').item.json.OPENAI_MODEL, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content }], response_format: { type: 'json_schema', json_schema: { name: 'pedido_frutitodo', strict: true, schema } } });
