const input = $('Normalizar entrada').first().json;
const response = $input.first().json;
const conversation = $('Buscar conversación GHL').first().json;
const conversationId = conversation?.body?.conversations?.[0]?.id || null;
const transcript = $('Armar transcripción').first().json;

let extracted = null;
let problem = null;
if (response.statusCode !== 200) {
  problem = `OpenAI respondió ${response.statusCode}`;
} else {
  try {
    extracted = JSON.parse(response.body?.choices?.[0]?.message?.content || 'null');
  } catch (error) {
    problem = 'La respuesta del modelo no es JSON válido';
  }
}

if (!transcript.inboundMessages) problem = `El cliente no ha escrito nada nuevo o GHL respondió ${transcript.readStatus}`;
if (!problem && extracted && !extracted.ok) problem = extracted.error || 'El mensaje de hoy no contiene un pedido';
const items = (extracted?.items || [])
  .map((item) => ({
    name: String(item.name || '').trim(),
    quantity: Number(item.quantity),
    ...(item.unit ? { unit: String(item.unit).trim() } : {}),
    ...(item.rawText ? { rawText: String(item.rawText).trim() } : {}),
    ...(String(item.unit || '').toUpperCase() === 'COP' ? { quantityKind: 'amount' } : {}),
  }))
  .filter((item) => item.name && item.quantity > 0);
if (!problem && !items.length) problem = 'El mensaje de hoy no contiene productos para comprar';

const name = String(extracted?.customer?.name || input.contactName || '').trim();
const phone = String(extracted?.customer?.phone || input.contactPhone || '').trim();
const address = String(extracted?.delivery?.address || input.contactAddress || '').trim();
const delivery = extracted?.delivery?.type === 'recogida'
  ? { type: 'recogida' }
  : { type: 'domicilio', ...(address ? { address } : {}) };
// Con pedido abierto se anexa salvo que el cliente pida explícitamente otro pedido. Sin pedido
// abierto siempre se crea uno nuevo. Si la app no respondió se conserva el ajuste anterior.
const orderAction = transcript.openOrder
  ? (extracted?.action === 'nuevo' ? 'new' : 'update')
  : (transcript.contextOk ? 'new' : 'update');
const rawOrderText = String(extracted?.rawOrderText || '').trim()
  || items.map((item) => item.rawText || `${item.quantity}${item.unit ? ` ${item.unit}` : ""} ${item.name}`).join('\n');

return [{
  json: {
    valid: !problem,
    problem,
    conversationId,
    idempotencySeed: transcript.idempotencySeed,
    summaryText: rawOrderText,
    payload: {
      locationId: input.locationId,
      contactId: input.contactId,
      conversationId: conversationId || undefined,
      customer: {
        name: name || undefined,
        phone: phone || undefined,
        document: extracted?.customer?.document || input.contactDocument || undefined,
      },
      delivery,
      paymentMethod: extracted?.paymentMethod || undefined,
      items,
      rawOrderText,
      notes: extracted?.notes || undefined,
      orderAction,
      contextUntil: transcript.contextUntil || undefined,
    },
  },
}];

const response = $input.first().json;
const status = response.statusCode;
const body = response.body || {};
const ok = status >= 200 && status < 300 && Boolean(body.order?.number);
return [{
  json: {
    ok,
    status,
    adjusted: ok && body.mode === 'updated',
    mode: body.mode || null,
    orderNumber: body.order?.number || null,
    duplicate: body.mode === 'duplicate',
    error: ok ? null : (body.message || `La app respondió ${status}`),
  },
}];

