={{ (() => {
  const cfg = $('Config').item.json;
  const p = $('Validar extracción').item.json.payload;
  const r = $('Resultado').item.json;
  const fields = [
    [cfg.CF_ULTIMO_PEDIDO_NUMERO, r.orderNumber],
    [cfg.CF_ULTIMO_PEDIDO_ESTADO, 'nuevo'],
    [cfg.CF_PEDIDO_RESUMEN, $('Validar extracción').item.json.summaryText],
    [cfg.CF_CEDULA, p.customer.document],
    [cfg.CF_METODO_PAGO, p.paymentMethod],
    [cfg.CF_DIRECCION, p.delivery.type === 'domicilio' ? p.delivery.address : null],
  ].filter(([key, value]) => key && value);
  const body = { customFields: fields.map(([key, value]) => ({ key, field_value: value })) };
  if (p.delivery.type === 'domicilio') body.address1 = p.delivery.address;
  return JSON.stringify(body);
})() }}
